/* ColorBlindForge 纯函数内核：Machado(2009) 色觉模拟 + WCAG 对比度 + CIE76 ΔE 审计 */
var CB = (function(){
  'use strict';
  /* Machado, Oliveira, Fernandes (2009) severity=1.0 线性 RGB 矩阵 */
  var MAT = {
    protanopia: [
      [0.152286, 1.052583, -0.204868],
      [0.114503, 0.786281, 0.099216],
      [-0.003882, -0.048116, 1.051998]
    ],
    deuteranopia: [
      [0.367322, 0.860646, -0.227968],
      [0.280085, 0.672501, 0.047413],
      [-0.011820, 0.042940, 0.968881]
    ],
    tritanopia: [
      [1.255528, -0.076749, -0.178779],
      [-0.078411, 0.930809, 0.147602],
      [0.004733, 0.691367, 0.303900]
    ]
  };
  var TYPES = [
    { id: 'protanopia', label: '红色盲 Protanopia', freq: '男性约 1%' },
    { id: 'deuteranopia', label: '绿色盲 Deuteranopia', freq: '男性约 1-2%' },
    { id: 'tritanopia', label: '蓝色盲 Tritanopia', freq: '约 0.01%' },
    { id: 'achromatopsia', label: '全色盲 Achromatopsia', freq: '约 0.003%' }
  ];
  function parseHex(s){
    if(typeof s !== 'string') return null;
    s = s.trim().replace(/^#/, '');
    if(/^[0-9a-fA-F]{3}$/.test(s)) s = s[0]+s[0]+s[1]+s[1]+s[2]+s[2];
    if(!/^[0-9a-fA-F]{6}$/.test(s)) return null;
    return { r: parseInt(s.slice(0,2),16), g: parseInt(s.slice(2,4),16), b: parseInt(s.slice(4,6),16) };
  }
  function toHex(c){
    function h(x){ x = Math.max(0, Math.min(255, Math.round(x))); return (x < 16 ? '0' : '') + x.toString(16); }
    return '#' + h(c.r) + h(c.g) + h(c.b);
  }
  function s2l(c){ c /= 255; return c <= 0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4); }
  function l2s(c){ c = Math.max(0, Math.min(1, c)); return 255 * (c <= 0.0031308 ? c*12.92 : 1.055*Math.pow(c, 1/2.4) - 0.055); }
  function simulate(hex, type){
    var c = typeof hex === 'string' ? parseHex(hex) : hex;
    if(!c) return null;
    var lr = s2l(c.r), lg = s2l(c.g), lb = s2l(c.b);
    if(type === 'normal') return toHex(c);
    if(type === 'achromatopsia'){
      var y = 0.2126*lr + 0.7152*lg + 0.0722*lb;
      return toHex({ r: l2s(y), g: l2s(y), b: l2s(y) });
    }
    var m = MAT[type];
    if(!m) throw new Error('未知色觉类型: ' + type);
    return toHex({
      r: l2s(m[0][0]*lr + m[0][1]*lg + m[0][2]*lb),
      g: l2s(m[1][0]*lr + m[1][1]*lg + m[1][2]*lb),
      b: l2s(m[2][0]*lr + m[2][1]*lg + m[2][2]*lb)
    });
  }
  /* WCAG 相对亮度与对比度 */
  function luminance(hex){
    var c = typeof hex === 'string' ? parseHex(hex) : hex;
    if(!c) return null;
    return 0.2126*s2l(c.r) + 0.7152*s2l(c.g) + 0.0722*s2l(c.b);
  }
  function contrast(a, b){
    var la = luminance(a), lb2 = luminance(b);
    if(la === null || lb2 === null) return null;
    var hi = Math.max(la, lb2), lo = Math.min(la, lb2);
    return (hi + 0.05) / (lo + 0.05);
  }
  function wcagLevel(ratio, large){
    if(large) return ratio >= 7 ? 'AAA' : (ratio >= 4.5 ? 'AAA' : (ratio >= 3 ? 'AA' : 'FAIL'));
    return ratio >= 7 ? 'AAA' : (ratio >= 4.5 ? 'AA' : (ratio >= 3 ? 'AA-Large' : 'FAIL'));
  }
  /* sRGB → Lab (D65)，CIE76 ΔE */
  function rgbToLab(hex){
    var c = typeof hex === 'string' ? parseHex(hex) : hex;
    if(!c) return null;
    var r = s2l(c.r), g = s2l(c.g), b = s2l(c.b);
    var x = (0.4124*r + 0.3576*g + 0.1805*b) / 0.95047;
    var y = 0.2126*r + 0.7152*g + 0.0722*b;
    var z = (0.0193*r + 0.1192*g + 0.9505*b) / 1.08883;
    function f(t){ return t > 0.008856 ? Math.pow(t, 1/3) : 7.787*t + 16/116; }
    var fx = f(x), fy = f(y), fz = f(z);
    return { L: 116*fy - 16, a: 500*(fx - fy), b: 200*(fy - fz) };
  }
  function deltaE(h1, h2){
    var a = rgbToLab(h1), b = rgbToLab(h2);
    if(!a || !b) return null;
    return Math.sqrt(Math.pow(a.L-b.L,2) + Math.pow(a.a-b.a,2) + Math.pow(a.b-b.b,2));
  }
  /* 调色板审计：各色觉类型下 ΔE 低于阈值的颜色对 */
  function audit(hexes, threshold){
    threshold = threshold || 12;
    var valid = hexes.map(parseHex).map(function(c, i){ return c ? { i: i, hex: toHex(c) } : null; }).filter(Boolean);
    var out = { threshold: threshold, types: {} };
    var all = [{ id: 'normal' }].concat(TYPES);
    for(var t=0;t<all.length;t++){
      var ty = all[t].id;
      var sims = valid.map(function(v){ return simulate(v.hex, ty); });
      var pairs = [];
      for(var i=0;i<valid.length;i++){
        for(var j=i+1;j<valid.length;j++){
          var de = deltaE(sims[i], sims[j]);
          if(de < threshold) pairs.push({ i: valid[i].i, j: valid[j].i, de: Math.round(de*10)/10 });
        }
      }
      out.types[ty] = { sims: sims, flagged: pairs };
    }
    return out;
  }
  return { types: TYPES, parseHex: parseHex, toHex: toHex, simulate: simulate,
           luminance: luminance, contrast: contrast, wcagLevel: wcagLevel,
           rgbToLab: rgbToLab, deltaE: deltaE, audit: audit };
})();
if(typeof module!=='undefined' && module.exports){ module.exports = CB; }
if(typeof window!=='undefined'){ window.__COLORBLINDFORGE__ = CB; }
